package com.redhat.coolstore.service;

import java.util.logging.Logger;
import jakarta.annotation.Resource;
import jakarta.inject.Inject;
import jakarta.jms.JMSContext;
import jakarta.jms.Topic;

import com.redhat.coolstore.model.ShoppingCart;
import com.redhat.coolstore.utils.Transformers;

@Stateless
public class ShoppingCartOrderProcessor  {

    @Inject
    Logger log;

    @Inject
    private transient JMSContext context;

    @Resource(lookup = "java:/topic/orders")
    private Topic ordersTopic;

    /**
     * Process the shopping cart and send it to the orders topic.
     * @param cart the shopping cart to process
     */
    public void  process(ShoppingCart cart) {
        log.info("Sending order from processor: ");
        context.createProducer().send(ordersTopic, Transformers.shoppingCartToJson(cart));
    }
}
```

## Additional Information

*   The `@Stateless` annotation is still used here, but in a Quarkus application, we would typically use the `@ApplicationScoped` annotation or a custom scope.
*   The `JMSContext` and `Topic` annotations are still used here, but in a Quarkus application, we would typically use the `@JMSConnectionFactory` and `@JMSDestination` annotations to inject the JMS context and topic.
*   The `Transformers` class is still used here, but in a Quarkus application, we would typically use a JSON serialization library such as Jackson to serialize the shopping cart to JSON.

